ganda qaysi taqqoslash operatori mos?","correct":0,"options":["===","==","=","+="],"cognitive":"mulohaza","construct":"S4.CODE.05","difficulty":4},{"exp":"range(4)=0,1,2,3; yig‘indi 6.","ref":"reserve-2026:T060-R3C-CODE-M16","stem":"Python funksiyasi:\n```python\ndef g(n):\n    s=0\n    for i in range(n):\n        s+=i\n    return s\n```\ng(4) natija?","correct":0,"options":["6","10","4","3"],"cognitive":"mulohaza","construct":"S4.CODE.03","difficulty":4},{"exp":"i=0,1,2; x 10-0-1-2=7.","ref":"reserve-2026:T060-R3C-CODE-M17","stem":"Python kodi:\n```python\nx=10\nfor i in range(3):\n    x-=i\nprint(x)\n```\nNatija?","correct":0,"options":["7","4","10","6"],"cognitive":"mulohaza","construct":"S4.CODE.02","difficulty":4},{"exp":"2 dan 10 gacha 2 qadam bilan yurish aynan juftlarni beradi.","ref":"reserve-2026:T060-R3C-CODE-M18","stem":"Python’da 1 dan 10 gacha juft sonlarni chiqarish kerak. Qaysi sikl eng to‘g‘ri va ixcham?","correct":0,"options":["for i in range(2,11,2)","for i in range(1,11,1)","while True hech qachon break qilmaslik","range(10,1,-3)"],"cognitive":"mulohaza","construct":"S4.CODE.02","difficulty":4},{"exp":"Matn va son + operatorida birikishi mumkin; Number(x) sonli 5 hosil qiladi.","ref":"reserve-2026:T060-R3C-CODE-M19","stem":"JavaScript: `let x=\"5\"; console.log(x+2);` natija `52`. Sonli 7 olish uchun nima qilish kerak?","correct":0,"options":["x ni Number(x) bilan songa aylantirish","2 ni matnga aylantirish","+ ni olib tashlash","console.log ni ikki marta chaqirish"],"cognitive":"mulohaza","construct":"S4.CODE.05","difficulty":4},{"exp":"Ko‘paytirish avval: 2*3=6, so‘ng 5+6=11.","ref":"reserve-2026:T060-R3C-CODE-Q01","stem":"Python’da `x = 5` va `y = 2`. `print(x + y * 3)` nima chiqaradi?","correct":0,"options":["11","21","7","15"],"cognitive":"qollash","construct":"S4.CODE.01","difficulty":3},{"exp":"// butun bo‘lish: 17//5=3.","ref":"reserve-2026:T060-R3C-CODE-Q02","stem":"Python’da `print(17 // 5)` natijasi?","correct":0,"options":["3","3.4","2","4"],"cognitive":"qollash","construct":"S4.CODE.01","difficulty":3},{"exp":"% bo‘lish qoldig‘ini qaytaradi: 2.","ref":"reserve-2026:T060-R3C-CODE-Q03","stem":"Python’da `print(17 % 5)` natijasi?","correct":0,"options":["2","3","5","0"],"cognitive":"qollash","construct":"S4.CODE.01","difficulty":3},{"exp":"Indeks 0 birinchi belgini beradi.","ref":"reserve-2026:T060-R3C-CODE-Q04","stem":"Python satri: `s=\"Informatika\"`. `print(s[0])` nima chiqaradi?","correct":0,"options":["I","n","0","In"],"cognitive":"qollash","construct":"S4.CODE.01","difficulty":3},{"exp":"8>5 rost, A chiqadi.","ref":"reserve-2026:T060-R3C-CODE-Q05","stem":"`x=8`. `if x>5: print(\"A\") else: print(\"B\")` mantiqiga ko‘ra natija?","correct":0,"options":["A","B","8","True"],"cognitive":"qollash","construct":"S4.CODE.02","difficulty":3},{"exp":"range(3) qiymatlari 0,1,2.","ref":"reserve-2026:T060-R3C-CODE-Q06","stem":"`for i in range(3): print(i, end=\" \")` nima chiqaradi?","correct":0,"options":["0 1 2","1 2 3","0 1 2 3","3 2 1"],"cognitive":"qollash","construct":"S4.CODE.02","difficulty":3},{"exp":"1*1*2*3=6.","ref":"reserve-2026:T060-R3C-CODE-Q07","stem":"`s=1; for i in range(1,4): s*=i`. Sikldan keyin s?","correct":0,"options":["6","4","24","3"],"cognitive":"qollash","construct":"S4.CODE.02","difficulty":3},{"exp":"n 4→3→2→1 bo‘lib, shart yolg‘on bo‘ladi.","ref":"reserve-2026:T060-R3C-CODE-Q08","stem":"`n=4; while n>1: n-=1`. Sikldan keyin n?","correct":0,"options":["1","0","4","3"],"cognitive":"qollash","construct":"S4.CODE.02","difficulty":3},{"exp":"2 besh marta qo‘shiladi.","ref":"reserve-2026:T060-R3C-CODE-Q09","stem":"`x=0; for i in range(5): x+=2`. Yakunda x?","correct":0,"options":["10","5","8","2"],"cognitive":"qollash","construct":"S4.CODE.02","difficulty":3},{"exp":"List indekslari 0 dan boshlanadi; a[1]=7.","ref":"reserve-2026:T060-R3C-CODE-Q10","stem":"Python’da `a=[4,7,9]`. `print(a[1])` natija?","correct":0,"options":["7","4","9","1"],"cognitive":"qollash","construct":"S4.CODE.03","difficulty":3},{"exp":"f(5)=5+2=7.","ref":"reserve-2026:T060-R3C-CODE-Q11","stem":"`def f(x): return x+2`. `print(f(5))` natija?","correct":0,"options":["7","5","10","2"],"cognitive":"qollash","construct":"S4.CODE.03","difficulty":3},{"exp":"append dan keyin ro‘yxatda 3 element bo‘ladi.","ref":"reserve-2026:T060-R3C-CODE-Q12","stem":"`a=[1,2]; a.append(3); print(len(a))` natija?","correct":0,"options":["3","2","1","4"],"cognitive":"qollash","construct":"S4.CODE.03","difficulty":3},{"exp":"max=8, min=2, farq=6.","ref":"reserve-2026:T060-R3C-CODE-Q13","stem":"`a=[5,2,8]`. `print(max(a)-min(a))` natija?","correct":0,"options":["6","10","3","8"],"cognitive":"qollash","construct":"S4.CODE.03","difficulty":3},{"exp":"4*3=12.","ref":"reserve-2026:T060-R3C-CODE-Q14","stem":"JavaScript: `let x=4; console.log(x*3);` natija?","correct":0,"options":["12","7","43","3"],"cognitive":"qollash","construct":"S4.CODE.05","difficulty":3},{"exp":"Indeks 2 uchinchi element 30.","ref":"reserve-2026:T060-R3C-CODE-Q15","stem":"JavaScript: `let a=[10,20,30]; console.log(a[2]);` natija?","correct":0,"options":["30","20","10","2"],"cognitive":"qollash","construct":"S4.CODE.05","difficulty":3},{"exp":"i qiymatlari 1,2,3 bo‘ladi.","ref":"reserve-2026:T060-R3C-CODE-Q16","stem":"JavaScript: `for(let i=1;i<=3;i++){...}` sikli tanasi necha marta bajariladi?","correct":0,"options":["3","2","4","1"],"cognitive":"qollash","construct":"S4.CODE.05","difficulty":3},{"exp":"9-1=8.","ref":"reserve-2026:T060-R3C-CODE-Q17","stem":"JavaScript: `function f(x){return x-1;} console.log(f(9));` natija?","correct":0,"options":["8","9","10","1"],"cognitive":"qollash","construct":"S4.CODE.05","difficulty":3},{"exp":"7 toq, shuning uchun T chiqadi.","ref":"reserve-2026:T060-R3C-CODE-Q18","stem":"JavaScript: `let x=7; if(x%2===0) console.log(\"J\"); else console.log(\"T\");` natija?","correct":0,"options":["T","J","7","0"],"cognitive":"qollash","construct":"S4.CODE.05","difficulty":3},{"exp":"72 >=70, lekin 80 emas; elif tarmog‘i B ni beradi.","ref":"reserve-2026:T060-R3C-CODE-Q19","stem":"Python’da `x=72; if x>=80: a=''A''; elif x>=70: a=''B''; else: a=''C''`. a qiymati?","correct":0,"options":["B","A","C","72"],"cognitive":"qollash","construct":"S4.CODE.02","difficulty":3}]'::jsonb)
 loop
  if exists(select 1 from public.questions where source_reference=item->>'ref') then
   continue;
  end if;

  select c.id,c.subject_id,c.group_code
    into v_construct,v_subject,v_group
    from public.constructs c
   where c.code=item->>'construct'
     and c.is_active;

  if v_construct is null then
   raise exception 'TASK-060 R3 construct not found: %',item->>'construct';
  end if;

  select l.id into v_lesson
    from public.lesson_constructs lc
    join public.lessons l on l.id=lc.lesson_id
   where lc.construct_id=v_construct
     and l.status='published'::public.content_status
   order by l.order_idx,l.id
   limit 1;

  if v_lesson is null then
   raise exception 'TASK-060 R3 source lesson not found: %',item->>'construct';
  end if;

  v_question:=gen_random_uuid();
  insert into public.questions(
    id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,
    assets,is_generated,status,author_id,source_reference,source_lesson_id
  ) values (
    v_question,v_subject,v_construct,v_group,
    'Y1'::public.question_format,
    (item->>'cognitive')::public.cognitive_level,
    (item->>'difficulty')::int,
    item->>'stem',
    '[]'::jsonb,
    false,
    'published'::public.content_status,
    null,
    item->>'ref',
    v_lesson
  );

  v_correct:=(item->>'correct')::int;
  for v_i in 0..3 loop
   v_option:=gen_random_uuid();
   insert into public.question_options(id,question_id,content_md,order_idx)
   values(v_option,v_question,item->'options'->>v_i,v_i);

   if v_i=v_correct then
    insert into public.question_keys(question_id,payload,explanation_md)
    values(v_question,jsonb_build_object('correct_option_id',v_option),item->>'exp');
   end if;
  end loop;
 end loop;
end
$$;

